def solve(N, B):
    A = []
    available_numbers = set()
    mex = 0

    for b in B:
        if b == -1:
            A.append(mex)
        else:
            while mex in available_numbers:
                mex += 1
            if mex == b:
                A.append(mex)
                mex += 1
            else:
                A.append(b)
                available_numbers.add(b)

    return A

